      method,
      path,
      outcome,
      signature,
      canonical_sha256,
    };

    if (reason) {
      ev.reason = reason;
    }

    evidence.push(ev);
  });

  const output = evidence.map((ev) => JSON.stringify(ev)).join("\n") + "\n";
  process.stdout.write(output);
}

main();

