          outcome = "rejected";
          reason = "unknown-key-id";
        } else {
          signature = createHmac("sha256", key).update(canonical, "utf8").digest("hex");
          outcome = "signed";
        }
      }
    }

    const ev: EvidenceRecord = {
      seq: i + 1,
      key_id: keyId,
      method,
      path,
      outcome,
      signature,
      canonical_sha256,
    };

    if (reason) {
      ev.reason = reason;
    }

    evidence.push(ev);
  });

  const output = evidence.map((ev) => JSON.stringify(ev)).join("\n") + "\n";
  process.stdout.write(output);
}

